2: // fit-to-bounds, and the CSS transform mapping world (0,0) into the viewport.
3: // Zero DOM here: this is the module the unit suite pins; viewport.js owns all
4: // DOM writes.
5: export const MIN_ZOOM = 0.25;
6: export const MAX_ZOOM = 2.0;
7: // DOCUMENTS: the pannable world frame for all per-stage ring geometry —
8: // widened for Stage 3's five rings and Stage 4's six (r_k = k * ringGap) so
9: // their left arcs and node cards stay reachable by pan and fit.
10: export const WORLD_BOUNDS = { minX: -3100, maxX: 600, minY: -900, maxY: 900 };
11: 
12: const clamp = (value, low, high) => Math.min(high, Math.max(low, value));
13: 
14: // CHECKS: createCamera rejects non-finite or non-positive inputs instead of
15: // producing a NaN transform that would blank the canvas, and clamps the
16: // resulting camera state into zoom and world bounds.
17: export function createCamera({ x = -360, y = 0, zoom = 0.78 } = {}) {
18:   if (!Number.isFinite(x) || !Number.isFinite(y) || !Number.isFinite(zoom) || zoom <= 0) {
19:     throw new Error('camera: x, y, and zoom must be finite numbers with zoom > 0');
20:   }
21:   return {
22:     x: clamp(x, WORLD_BOUNDS.minX, WORLD_BOUNDS.maxX),
23:     y: clamp(y, WORLD_BOUNDS.minY, WORLD_BOUNDS.maxY),
24:     zoom: clamp(zoom, MIN_ZOOM, MAX_ZOOM),
25:   };
26: }
27: 
28: // Pan: the world center moves inversely to zoom under a fixed screen delta.
29: export function panCamera(cam, dxScreen, dyScreen) {
30:   return createCamera({
31:     x: cam.x - dxScreen / cam.zoom,
32:     y: cam.y - dyScreen / cam.zoom,
33:     zoom: cam.zoom,
34:   });
35: }
36: 
37: // CHECKS: zoom-at-cursor keeps the world point under the cursor offset (screen
38: // px from the viewport center) stationary while the scale changes.
39: export function zoomCameraAt(cam, factor, cursorOffsetX = 0, cursorOffsetY = 0) {
40:   const nextZoom = clamp(cam.zoom * factor, MIN_ZOOM, MAX_ZOOM);
41:   const worldX = cam.x + cursorOffsetX / cam.zoom;
42:   const worldY = cam.y + cursorOffsetY / cam.zoom;
43:   return createCamera({
44:     x: worldX - cursorOffsetX / nextZoom,
45:     y: worldY - cursorOffsetY / nextZoom,
46:     zoom: nextZoom,
47:   });
48: }
49: 
50: // Fit: center the bounds and scale so they land inside a screen margin.
51: export function fitCameraToBounds(bounds, viewportWidth, viewportHeight, padding = 48) {
52:   const spanX = bounds.maxX - bounds.minX;
53:   const spanY = bounds.maxY - bounds.minY;
54:   return createCamera({
55:     x: (bounds.minX + bounds.maxX) / 2,
56:     y: (bounds.minY + bounds.maxY) / 2,
57:     zoom: Math.min((viewportWidth - 2 * padding) / spanX, (viewportHeight - 2 * padding) / spanY),
58:   });
59: }
