61: // CHECKS: auto-refit fires only when the world bounds, scaled by the current
62: // zoom, overflow the viewport screen box — a camera that already frames the
63: // world never triggers a refit.
64: export function worldExceedsViewport(bounds, zoom, viewportWidth, viewportHeight) {
65:   return (
66:     (bounds.maxX - bounds.minX) * zoom > viewportWidth ||
67:     (bounds.maxY - bounds.minY) * zoom > viewportHeight
68:   );
69: }
