71: // CHECKS: the auto-refit boundary contract as an armed/cancelled machine —
72: // a manual camera action (pointer drag, wheel, +/- or Fit buttons) cancels
73: // the pending refit, and only a stage/topology or user-count change re-arms
74: // it. Named counter-example (pinned in test/panel/camera.test.js): after a
75: // manual btn-zoom-in, the next silent tick must NOT refit.
76: export function createAutoRefit() {
77:   let armed = true;
78:   return {
79:     get armed() {
80:       return armed;
81:     },
82:     cancel() {
83:       armed = false;
84:     },
85:     rearm() {
86:       armed = true;
87:     },
88:     // Whether the same fit routine as btn-zoom-fit must run right now.
89:     shouldRefit(bounds, zoom, viewportWidth, viewportHeight) {
90:       return armed && worldExceedsViewport(bounds, zoom, viewportWidth, viewportHeight);
91:     },
92:   };
93: }
