95: // CHECKS: the CSS transform maps world (wx, wy) to
96: // (w/2 + (wx - cam.x) * zoom, h/2 + (wy - cam.y) * zoom).
97: export function formatWorldTransform(cam, viewportWidth, viewportHeight) {
98:   const tx = Math.round(viewportWidth / 2 - cam.x * cam.zoom);
99:   const ty = Math.round(viewportHeight / 2 - cam.y * cam.zoom);
100:   return `translate(${tx}px, ${ty}px) scale(${Number(cam.zoom.toFixed(4))})`;
