```js
export function createNetwork({ subnet = '10' } = {}) {
  if (!/^\d+$/.test(String(subnet))) throw new Error(`network: subnet must be numeric, got ${subnet}`);
  const servers = new Map();
  let gateway = null;
  function validate(addr) {...}
  function isCrossSubnet(address) {
    return address.split('.')[0] !== subnet;
  }
  function resolve(address) {
    validate(address);
    const server = servers.get(address);
    if (!server) throw new Error(`network: no server at ${address}`);
    return server;
  }
  function deliverLocal({ id, from, to, request, atTick, isYou }) { ... }
  return {
    registerServer, resolve,
    attachGateway(fn) { gateway = fn; },
    send({ from, to, request }) {
      validate(from);
      validate(to);
      if (gateway && isCrossSubnet(to)) {
        return gateway({ kind: 'send', from, to, request });
      }
      const server = resolve(to);
      const response = server.handleRequest(request);
      return { from, to, request, response };
    },
    deliverToQueue({ id, from, to, request, atTick, isYou = false }) {
      validate(from);
      validate(to);
      if (gateway && isCrossSubnet(to)) {
        return gateway({ kind: 'queue', id, from, to, request, atTick, isYou });
      }
      const server = resolve(to);
      server.enqueue({ id, from, to, request, atTick, isYou });
    },
    // A frame the Router has already forwarded into this subnet is local here.
    receiveCrossSubnet(record) {
      if (record.kind === 'queue') {
        const server = resolve(record.to);
        server.enqueue({ id: record.id, from: record.from, to: record.to, request: record.request, atTick: record.atTick, isYou: record.isYou });
        return null;
      }
      const server = resolve(record.to);
      const response = server.handleRequest(record.request);
      return { from: record.from, to: record.to, request: record.request, response };
    },
  };
}
```

