// DOCUMENTS: the Stage 6 cross-subnet Router — joins two Network instances
// (10.x and 20.x) ...
const MINI_IP = /^\d+\.\d+$/;

export function createRouter({ leftAddress = '10.65', rightAddress = '20.1' } = {}) {
  for (const [name, addr] of [['leftAddress', leftAddress], ['rightAddress', rightAddress]]) {
    if (!MINI_IP.test(addr)) throw new Error(`router: invalid mini-IP address ${name}=${addr}`);
  }
  const leftNet = leftAddress.split('.')[0];
  const rightNet = rightAddress.split('.')[0];
  if (leftNet === rightNet) throw new Error(`router: both interfaces live in subnet ${leftNet}`);
  let routed = 0;
  let lastRoute = null;
  const handleRequest = (request = 'GET /') => `200 router ${rightAddress}`;
  function forward(record, far) {
    routed += 1;
    lastRoute = `${record.from} -> ${record.to} via ${...}`;
    return far.receiveCrossSubnet(record);
  }
  return {
    get leftAddress() { return leftAddress; },
    get rightAddress() { return rightAddress; },
    handleRequest,
    join(leftNetwork, rightNetwork) {
      leftNetwork.attachGateway((record) => forward(record, rightNetwork));
      rightNetwork.attachGateway((record) => forward(record, leftNetwork));
      leftNetwork.registerServer(leftAddress, { handleRequest });
      rightNetwork.registerServer(rightAddress, { handleRequest });
      return this;
    },
    snapshot() { return { leftAddress, rightAddress, routed, lastRoute }; },
  };
}
