// DOCUMENTS: the Stage 6 trace wrapper — hosted browser paths
// ("<host>/<path>") prepend two DNS hops (Browser -> DNS 10.60 ask, then the
// DNS answer) before the resolved path is handed to the Stage 5 machine
// unmodified, so the host-less Stage 6 story stays byte-identical to
// Stage 5's. A name the resolver answers NX short-circuits: DNS ask + NX
// answer + the browser rendering the NX card, and no GET is emitted.
//
// CHECKS: the wrapper fails loud at construction unless stage is 6 and a DNS
// component is attached.
import { createTraceMachine } from './trace.js';

export function createStage6Trace({ stage, dns, ...config }) {
  if (stage !== 6) throw new Error(`trace-stage6: stage must be 6, got ${stage}`);
  if (!dns) throw new Error('trace-stage6: no DNS component attached');
  const inner = createTraceMachine({ ...config, stage: 5 });

  // Host split on the first "/": "example.com/about" -> { host, rest };
  // "/about" (or any path starting with "/") is host-less; a bare name
  // ("example.com") resolves with the root path.
  function splitHost(path) {
    const raw = String(path ?? '');
    const slashAt = raw.indexOf('/');
    if (slashAt === 0) return null;
    if (slashAt === -1) return { host: raw, rest: '/' };
    return { host: raw.slice(0, slashAt), rest: raw.slice(slashAt) };
  }
