// DOCUMENTS: the Stage 6 DNS resolver — an authoritative name table plus a
// resolver cache with tick-based TTL, mirroring the Cache ledger pattern
// (js/sim/cache.js): a lookup consults the authoritative table only on a
// cache miss or an expired entry; a hit inside ttlTicks increments
// cachedHits with no authoritative consult. Deterministic by construction:
// no clock, no RNG — time arrives as the `currentTick` argument.
//
// CHECKS: the constructor rejects an address that is not a two-number
// mini-IP and a ttlTicks that is not a positive integer (fail-loud over
// silent mis-configuration). An unknown name answers { status: 'NX' } — the
// NX case is a normal answer at the DNS layer, not a throw (the fail-loud
// throw rule applies to cross-subnet addresses in network.js).
export function createDns({ address = '10.60', ttlTicks = 300 } = {}) {
  if (!/^\d+\.\d+$/.test(address)) {
    throw new Error(`dns: invalid mini-IP address ${address}`);
  }
  if (!Number.isInteger(ttlTicks) || ttlTicks < 1) {
    throw new Error(`dns: ttlTicks must be a positive integer, got ${ttlTicks}`);
  }
  // Authoritative table lives in-component: Stage 6a resolves example.com;
  // Stage 6b adds the CDN name.
  const AUTHORITATIVE = new Map([['example.com', '10.1']]);
  const cache = new Map(); // name -> { name, target, expiresAtTick }
  let lookups = 0;
  let cachedHits = 0;
  let authoritative = 0;
  let evictions = 0;
  let lastLookup = null;

  // CHECKS: an expired entry is deleted before it can answer — the named
  // counter-example (an expired entry answered from the ledger) is pinned in
  // test/sim/dns.test.js.
  function evictExpired(currentTick = 0) {
    for (const entry of cache.values()) {
      if (currentTick >= entry.expiresAtTick) {
        cache.delete(entry.name);
        evictions += 1;
      }
    }
  }

  function lookup(name, currentTick = 0) {
    lookups += 1;
    const entry = cache.get(name);
    if (entry && currentTick < entry.expiresAtTick) {
      cachedHits += 1;
      lastLookup = { name, status: 'HIT', target: entry.target, atTick: currentTick };
      return { status: 'HIT', target: entry.target };
    }
    if (entry) {
      cache.delete(name);
      evictions += 1;
    }
    authoritative += 1;
    const record = AUTHORITATIVE.get(name);
    if (!record) {
      lastLookup = { name, status: 'NX', atTick: currentTick };
      return { status: 'NX' };
    }
    cache.set(name, { name, target: record, expiresAtTick: currentTick + ttlTicks });
    lastLookup = { name, status: 'MISS', target: record, atTick: currentTick };
    return { status: 'MISS', target: record };
  }

  function snapshot(currentTick = 0) {
    evictExpired(currentTick);
    return {
      address,
      ttlTicks,
      lookups,
      cachedHits,
      authoritative,
      evictions,
      lastLookup,
      cache: [...cache.values()].map((e) => ({
        name: e.name,
        target: e.target,
        expiresAtTick: e.expiresAtTick,
        ttlRemaining: e.expiresAtTick - currentTick,
      })),
    };
  }

  return {
    get address() {
      return address;
    },
    lookup,
    evictExpired,
    snapshot,
  };
}

// DOCUMENTS: the Stage 6 cross-subnet Router — joins two Network instances
// (the 10.x fabric and the 20.x fabric) so a frame addressed outside its own
// subnet crosses exactly one router hop: the near network hands the record
// to the router's gateway closure, the router counts it in `routed`, and the
// far network delivers it locally. `isYou` rides through untouched on queue
// deliveries. In Stage 6a nothing lives in subnet 20 besides the router's
// own presence: its 20-side interface (20.1) is the only reachable target,
// and an unregistered 20.x host (20.9) fails loud through the far network's
// resolve.
//
// CHECKS: the constructor rejects a non two-number mini-IP interface and two
// interfaces on the same subnet (a router between one subnet is not a
// router).
const MINI_IP = /^\d+\.\d+$/;

export function createRouter({ leftAddress = '10.65', rightAddress = '20.1' } = {}) {
  for (const [name, addr] of [
    ['leftAddress', leftAddress],
    ['rightAddress', rightAddress],
  ]) {
    if (!MINI_IP.test(addr)) {
      throw new Error(`router: invalid mini-IP address ${name}=${addr}`);
    }
  }
  const leftNet = String(leftAddress).split('.')[0];
  const rightNet = String(rightAddress).split('.')[0];
  if (leftNet === rightNet) {
    throw new Error(`router: both interfaces live in subnet ${leftNet}`);
  }
  let routed = 0;
  let lastRoute = null;

  // The router's own interface answer — in Stage 6a the 20.1 side is the
  // only thing alive in subnet 20 (Stage 6b occupies it with the CDN edge).
  const handleRequest = () => `200 router ${rightAddress}`;

  // CHECKS: one forward call per cross-subnet frame — `routed` counts frames
  // entering the router, so a delivery that then fails loud in the far
  // subnet still counted its single hop (pinned in test/sim/router.test.js).
  function forward(record, farNetwork) {
    routed += 1;
    lastRoute = `${record.from} -> ${record.to} via ${leftAddress} ⇄ ${rightAddress}`;
    return farNetwork.receiveCrossSubnet(record);
  }

  return {
    get leftAddress() {
      return leftAddress;
    },
    get rightAddress() {
      return rightAddress;
    },

    handleRequest,

    join(leftNetwork, rightNetwork) {
      leftNetwork.attachGateway((record) => forward(record, rightNetwork));
      rightNetwork.attachGateway((record) => forward(record, leftNetwork));
      leftNetwork.registerServer(leftAddress, { handleRequest });
      rightNetwork.registerServer(rightAddress, { handleRequest });
      return this;
    },

    snapshot() {
      return { leftAddress, rightAddress, routed, lastRoute };
    },
  };
}

// DOCUMENTS: the network — the wiring that lets two-number mini-IP
// addressable components exchange messages. Today it carries slim HTTP
// requests to a registered server; later stages attach more components
// without changing the send/enqueue contract. Stage 6 adds cross-subnet
// support: a network owns one subnet, and a frame addressed outside it is
// handed to the attached Router gateway instead of resolved locally — the
// far network delivers it after the single router hop.
//
// CHECKS: every address crossing the wire is validated as a two-number
// mini-IP (<net>.<host>), and sends to unregistered hosts fail loud —
// including cross-subnet sends into an unregistered far host (20.9), whose
// error surfaces from the far network's own resolve.
const MINI_IP = /^\d+\.\d+$/;

export function createNetwork({ subnet = '10' } = {}) {
  if (!/^\d+$/.test(String(subnet))) {
    throw new Error(`network: subnet must be a numeric label, got ${subnet}`);
  }
  const servers = new Map();
  let gateway = null; // router closure: record -> far network delivery

  function validate(addr) {
    if (!MINI_IP.test(addr)) {
      throw new Error(`network: invalid mini-IP address ${addr}`);
    }
  }

  function resolve(address) {
    validate(address);
    const server = servers.get(address);
    if (!server) {
      throw new Error(`network: no server at ${address}`);
    }
    return server;
  }

  // A target outside this network's own subnet crosses the router; without
  // an attached gateway the local resolve throws its usual no-server error.
  function isCrossSubnet(address) {
    return String(address).split('.')[0] !== String(subnet);
  }

  return {
    registerServer(address, server) {
      validate(address);
      servers.set(address, server);
    },

    resolve,

    attachGateway(fn) {
      gateway = fn;
    },

    send({ from, to, request }) {
      validate(from);
      validate(to);
      if (gateway && isCrossSubnet(to)) {
        return gateway({ kind: 'send', from, to, request });
      }
      const server = resolve(to);
      const response = server.handleRequest(request);
      return { from, to, request, response };
    },

    // `isYou` rides through untouched: the engine marks the learner's own
    // interactive-browser request, the server stores it on the queue row.
    deliverToQueue({ id, from, to, request, atTick, isYou = false }) {
      validate(from);
      validate(to);
      if (gateway && isCrossSubnet(to)) {
        return gateway({ kind: 'queue', id, from, to, request, atTick, isYou });
      }
      const server = resolve(to);
      server.enqueue({ id, from, to, request, atTick, isYou });
    },

    // A frame the Router has already forwarded into this subnet is local
    // here: deliver it by the same send/enqueue contract, no second hop.
    receiveCrossSubnet(record) {
      if (record.kind === 'queue') {
        const server = resolve(record.to);
        server.enqueue({
          id: record.id,
          from: record.from,
          to: record.to,
          request: record.request,
          atTick: record.atTick,
          isYou: record.isYou,
        });
        return null;
      }
      const server = resolve(record.to);
      const response = server.handleRequest(record.request);
      return { from: record.from, to: record.to, request: record.request, response };
    },
  };
}

// DOCUMENTS: the Stage 6 trace wrapper around the hop-by-hop machine. A
// hosted browser path ("<host>/<path>") prepends two DNS hops — Browser ->
// DNS 10.60 ask, then the DNS answer — before the resolved path is handed to
// an inner Stage 5 machine unmodified, so the Stage 6 host-less story stays
// byte-identical to Stage 5's (named counter-example: GET /about on Stage 6
// keeps the Stage 5 hop count and hop texts). A name the resolver answers NX
// short-circuits: DNS ask + "NX no record" answer + the browser rendering
// the NX card, and no GET is emitted.
//
// CHECKS: the wrapper fails loud at construction unless the stage is 6 and a
// DNS component is attached. Hosted runs delegate to a fresh inner machine
// per run, so a trace abandoned mid-flight (host-less then hosted) starts
// clean instead of riding the previous run's hop state.
import { createTraceMachine } from './trace.js';

export function createStage6Trace({ stage, dns, ...config }) {
  if (stage !== 6) {
    throw new Error(`trace-stage6: stage must be 6, got ${stage}`);
  }
  if (!dns) {
    throw new Error('trace-stage6: no DNS component attached');
  }
  const inner = createTraceMachine({ ...config, stage: 5 });

  // Host split on the first "/": "example.com/about" -> { host, rest }.
  // A path starting with "/" (or any string with no leading host token) is
  // host-less; a bare name ("example.com") resolves against the root path.
  function splitHost(path) {
    const raw = String(path ?? '');
    const slashAt = raw.indexOf('/');
    if (slashAt <= 0) return null;
    return { host: raw.slice(0, slashAt), rest: raw.slice(slashAt) };
  }

  // Per-run hosted state; null means the current trace is host-less and the
  // inner machine owns everything.
  let run = null;

  function hostTrace({ hop, response, status, body, dnsAnswer }) {
    return {
      hop,
      method: run.method,
      path: `${run.host}${run.rest}`,
      request: `${run.method} ${run.host}${run.rest}`,
      from: run.from,
      targetServer: null,
      cacheStatus: null,
      dbOp: null,
      dbStale: false,
      asyncJob: false,
      response,
      status,
      body,
      routeId: null,
      hosted: true,
      nx: run.nx,
      dnsName: run.host,
      dnsAddress: dns.address,
      dnsAnswer,
    };
  }

  function startRun(split, method, from) {
    return {
      host: split.host,
      rest: split.rest,
      method,
      from,
      phase: 'ask',
      nx: false,
      done: false,
      answer: null,
      inner: createTraceMachine({ ...config, stage: 5 }),
    };
  }

  function answerFrame(result) {
    if (result.status === 'NX') {
      run.nx = true;
      run.answer = 'NX no record';
      run.phase = 'nx-render';
      return `${dns.address} -> ${run.from} | NX no record`;
    }
    const how = result.status === 'HIT' ? 'cache HIT' : 'authoritative';
    run.answer = `${run.host} is ${result.target} (${how})`;
    run.phase = 'resolved';
    return `${dns.address} -> ${run.from} | ${run.answer}`;
  }

  return {
    // One hop per call, mirroring the inner machine's contract: the hop's
    // lastFrame string, or null when nothing moved.
    step({ method = 'GET', path = '/about', from = '10.2' } = {}) {
      const split = splitHost(path);
      if (!split) {
        run = null;
        return inner.step({ method, path, from });
      }
      if (!run || run.done) run = startRun(split, method, from);
      if (run.phase === 'ask') {
        run.phase = 'answer';
        return `${run.from} -> ${dns.address} | resolve ${run.host}`;
      }
      if (run.phase === 'answer') {
        const result = dns.lookup(run.host, config.getTick());
        return answerFrame(result);
      }
      if (run.phase === 'nx-render') {
        run.done = true;
        // The NX record is what the browser card renders; no GET is emitted,
        // so nothing is served and no queue row exists.
        config.onFinish({
          from: run.from,
          to: run.from,
          request: `${run.method} ${run.host}${run.rest}`,
          response: 'NX no record',
        });
        return `Browser ${run.from} renders NX — no record for ${run.host}`;
      }
      // resolved: the browser emits the GET with the resolved target; the
      // inner Stage 5 machine runs the tail of the story unmodified.
      const frame = run.inner.step({ method: run.method, path: run.rest, from: run.from });
      if (run.inner.snapshot().hop >= 8) run.done = true;
      return frame;
    },

    snapshot() {
      if (!run) {
        return {
          ...inner.snapshot(),
          hosted: false,
          nx: false,
          dnsName: null,
          dnsAddress: dns.address,
          dnsAnswer: null,
        };
      }
      if (run.phase === 'ask') {
        return hostTrace({ hop: 1, response: null, status: null, body: null, dnsAnswer: null });
      }
      if (run.phase === 'answer' || run.phase === 'nx-render') {
        return hostTrace({
          hop: 2,
          response: run.nx ? 'NX no record' : null,
          status: run.nx ? 'NX' : null,
          body: run.nx ? 'no record' : null,
          dnsAnswer: run.answer,
        });
      }
      if (run.phase === 'resolved') {
        return {
          ...run.inner.snapshot(),
          hop: 2 + run.inner.snapshot().hop,
          hosted: true,
          nx: false,
          dnsName: run.host,
          dnsAddress: dns.address,
          dnsAnswer: run.answer,
        };
      }
      // nx done: the browser rendered the NX card (hop 3 of 3).
      return hostTrace({
        hop: 3,
        response: 'NX no record',
        status: 'NX',
        body: 'no record',
        dnsAnswer: run.answer,
      });
    },
  };
}

// DOCUMENTS: the tick loop — each step() advances exactly one discrete
// tick: users emit request events over the network into the server pool's
// (or load balancer's) queues, the pool consumes up to its per-tick work
// budget and emits response events, then a snapshot is exposed as UI state.
// The newest served exchange is kept in `lastExchange` so the panel can
// show what actually moved on the wire. The interactive single-request
// trace is the hop-by-hop state machine in trace.js, driven one hop per
// traceHop() call across the same network/LB/queue/cache machinery the
// crowd uses — it does not fake a shortcut.
//
// Stage 6 instantiates DNS 10.60 (tick-TTL resolver ledger) and the
// cross-subnet Router (10.65 ⇄ 20.1) and hands the trace to the Stage 6
// wrapper in trace-stage6.js; the crowd path stays host-less and untouched.
//
// PINS: a fixed seed with a fixed action sequence replays the identical
// tick sequence — pinned by "same seed replays the identical tick sequence"
// in test/sim/engine.test.js.
//
// CHECKS: constructor validates config ranges via its components (seed is
// coerced uint32; arrivalProb must be within [0, 1]; stage must be 1-6).
import { createRng } from './rng.js';
import { createNetwork } from './network.js';
import { createBrowser } from './browser.js';
import { createWebServer } from './webserver.js';
import { createLoadBalancer } from './loadbalancer.js';
import { createCache } from './cache.js';
import { createDatabase } from './database.js';
import { createWorkerQueue } from './queue.js';
import { createDns } from './dns.js';
import { createRouter } from './router.js';
import { createUsers } from './users.js';
import { createTraceMachine } from './trace.js';
import { createStage6Trace } from './trace-stage6.js';

export function createEngine({
  seed = 42,
  users = 5,
  serviceRate = 4,
  arrivalProb = 0.5,
  serverAddress = '10.1',
  stage = 1,
  backendAddresses = ['10.11', '10.12'],
  ttlTicks = 10,
  cacheAddress = '10.20',
  replicationLagTicks = 3,
  dbPrimaryAddress = '10.30',
  dbReplicaAddress = '10.31',
  workerQueueAddress = '10.40',
  workerAddress = '10.41',
  jobDurationTicks = 2,
  dnsAddress = '10.60',
  dnsTtlTicks = 300,
  routerLeftAddress = '10.65',
  routerRightAddress = '20.1',
} = {}) {
  if (typeof arrivalProb !== 'number' || arrivalProb < 0 || arrivalProb > 1) {
    throw new Error(`engine: arrivalProb must be within [0, 1], got ${arrivalProb}`);
  }
  if (stage !== 1 && stage !== 2 && stage !== 3 && stage !== 4 && stage !== 5 && stage !== 6) {
    throw new Error(`engine: stage must be 1, 2, 3, 4, 5, or 6, got ${stage}`);
  }
  const rng = createRng(seed);
  const network = createNetwork();
  const cache = stage >= 3 ? createCache({ address: cacheAddress, ttlTicks }) : null;
  const database =
    stage >= 4
      ? createDatabase({
          primaryAddress: dbPrimaryAddress,
          replicaAddress: dbReplicaAddress,
          replicationLagTicks,
        })
      : null;
  const workerQueue =
    stage >= 5
      ? createWorkerQueue({
          address: workerQueueAddress,
          workerAddress,
          jobDurationTicks,
        })
      : null;
  const dns = stage >= 6 ? createDns({ address: dnsAddress, ttlTicks: dnsTtlTicks }) : null;
  const router =
    stage >= 6
      ? createRouter({ leftAddress: routerLeftAddress, rightAddress: routerRightAddress })
      : null;
  // Stage 6 joins the 20.x fabric through the Router: nothing registers
  // there in 6a besides the router's own 20-side interface.
  const subnet20 = stage >= 6 ? createNetwork({ subnet: '20' }) : null;
  if (router) router.join(network, subnet20);
  let servers;
  let lb = null;
  if (stage === 1) {
    const server = createWebServer({ address: serverAddress, serviceRate });
    network.registerServer(serverAddress, server);
    servers = [server];
  } else {
    // Stage 2 wires the LB in front of two duplicated backends; Stage 3
    // attaches the shared cache-aside Cache to both backends; Stage 4 adds
    // the primary/replica Database; Stage 5 adds the WorkerQueue & Worker;
    // Stage 6 keeps that stack and adds DNS + Router.
    servers = backendAddresses.map((addr) =>
      createWebServer({ address: addr, serviceRate, cache, database, workerQueue }),
    );
    for (const s of servers) network.registerServer(s.address, s);
    lb = createLoadBalancer({ address: serverAddress, backends: backendAddresses, network });
    network.registerServer(serverAddress, lb);
  }
  // The learner's own interactive client shares the crowd's network and
  // server pool but keeps its own browser and address; users.js keeps its
  // addresses so seeded tick sequences stay identical (PINS above).
  const clientBrowser = createBrowser({ name: 'Browser (You)', address: '10.2', network });
  const userPool = createUsers({ count: users, serverAddress });
  let tick = 0;
  let lastExchange = null;
  let lastMatchedRoute = null;
  let lastFrame = null;

  // The trace machine owns the hop-by-hop trace state; the engine owns the
  // clock, the served-exchange record, and browser delivery — the machine
  // calls back into these closures as hops execute.
  const traceConfig = {
    stage,
    serverAddress,
    servers,
    lb,
    network,
    cache,
    database,
    workerQueue,
    dns,
    bumpTick: () => {
      tick += 1;
      return tick;
    },
    getTick: () => tick,
    onServe: (exchange) => {
      lastExchange = exchange;
      lastMatchedRoute = exchange.routeId;
    },
    onFinish: (record) => {
      userPool.receiveResponse(record);
      if (record.from === '10.2') clientBrowser.receiveResponse(record);
    },
  };
  const traceMachine =
    stage === 6 ? createStage6Trace(traceConfig) : createTraceMachine(traceConfig);

  return {
    step() {
      tick += 1;
      // TTL eviction happens once per tick, before anything is served:
      // expired entries are gone before this tick's work is priced.
      if (cache) cache.evictExpired(tick);
      if (dns) dns.evictExpired(tick);
      // Stage 4+: replication advances one tick at a time.
      if (database) database.stepReplication(tick);
      // Stage 5: worker queue advances jobs and writes to database.
      if (workerQueue) workerQueue.step(database, tick);
      const arrivals = userPool.step(rng, arrivalProb);
      for (const r of arrivals) {
        network.deliverToQueue({
          id: `${tick}:${r.userId}`,
          from: r.from,
          to: r.to,
          request: r.request,
          atTick: tick,
        });
      }
      const servedBatch = servers.flatMap((s) => s.step(tick));
      if (servedBatch.length > 0) {
        lastExchange = servedBatch[servedBatch.length - 1];
        lastMatchedRoute = lastExchange.routeId;
        lastFrame = `${lastExchange.from} -> ${lastExchange.to} | ${lastExchange.request} => ${lastExchange.response}`;
        for (const item of servedBatch) {
          // Every served exchange is delivered back to its originating
          // browser; the learner's own interactive client additionally
          // renders anything it originated (trace items or 10.2 crowd rays).
          userPool.receiveResponse(item);
          if (item.isYou || item.from === '10.2') clientBrowser.receiveResponse(item);
        }
      }
      return this.snapshot();
    },

    // One hop per call, delegated to the trace machine: 4 hops in Stage 1
    // (emit, route, serve, render); 5 in Stage 2 (LB round-robin between
    // route and serve); 6 in Stage 3 (cache check, then response emit);
    // 7 in Stage 4 (the database hop inserted after the cache check); 8 in
    // Stage 5; 10 in Stage 6 when the path carries a host (2 DNS hops first)
    // and the Stage 5 8 when it does not.
    // `from` is the mini-IP of the browser the trace originates from
    // (default the learner's own 10.2).
    traceHop({ method = 'GET', path = '/about', from = '10.2' } = {}) {
      const frame = traceMachine.step({ method, path, from });
      if (frame !== null) lastFrame = frame;
      return this.snapshot();
    },

    setUsers(n) {
      userPool.setCount(n);
    },

    snapshot() {
      const serverSnapshots = servers.map((s) => ({
        address: s.address,
        ...s.metrics(),
        queue: s.queueSnapshot(),
        files: s.filesSnapshot(),
      }));
      const queueDepth = serverSnapshots.reduce((sum, s) => sum + s.queueDepth, 0);
      const served = serverSnapshots.reduce((sum, s) => sum + s.served, 0);
      const active = serverSnapshots.filter((s) => s.served > 0);
      const avgLatencyTicks =
        active.length === 0
          ? 0
          : active.reduce((sum, s) => sum + s.avgLatencyTicks, 0) / active.length;
      return {
        stage,
        tick,
        users: userPool.getCount(),
        serverAddress,
        queueDepth,
        served,
        avgLatencyTicks,
        lastExchange,
        queue: serverSnapshots[0].queue,
        files: serverSnapshots[0].files,
        servers: serverSnapshots,
        loadBalancer: lb ? lb.snapshot() : null,
        cache: cache ? cache.snapshot(tick) : null,
        database: database ? database.snapshot(tick) : null,
        workerQueue: workerQueue ? workerQueue.snapshot(tick) : null,
        dns: dns ? dns.snapshot(tick) : null,
        router: router ? router.snapshot() : null,
        lastMatchedRoute,
        lastFrame,
        browserDisplay: clientBrowser.last(),
        browsers: userPool.getBrowsers(),
        trace: traceMachine.snapshot(),
      };
    },
  };
}

