// DOCUMENTS: browser-slot arc geometry, split from layout.js by
// responsibility (guard-file-size: layout.js sits at its 300-line cap and
// Stage 6 needs room for its 8-ring registry). The satellite arcs place the
// non-expanded browsers around the outer client ring; slot 0 always keeps
// the expanded card's 180° seat.
export function computeSatellites(users, outerRadius) {
  const count = Math.max(0, Math.round(users));
  const leftCount = Math.ceil(count / 2);
  const rightCount = count - leftCount;
  const satellites = [];
  const place = (arcCount, startAngle) => {
    for (let j = 0; j < arcCount; j += 1) {
      const angleDeg = startAngle + ((j + 1) / (arcCount + 1)) * 37;
      const { x, y } = polarToWorld(outerRadius, angleDeg);
      satellites.push({ index: satellites.length, x, y, angleDeg });
    }
  };
  place(leftCount, 135);
  place(rightCount, 188);
  return satellites;
}

export function polarToWorld(radius, angleDeg) {
  const rad = (angleDeg * Math.PI) / 180;
  return { x: Math.round(radius * Math.cos(rad)), y: Math.round(radius * Math.sin(rad)) };
}

// DOCUMENTS: Stage 6 orrery additions — the 8-ring registry (DNS 10.60 on
// Ring 7, the Router side-card beside the 10.x hub on Ring 6) and the two
// wires the stage adds (browser -> DNS ask, Network -> Router). Split from
// layout.js by responsibility (guard-file-size: layout.js sits at its
// 300-line cap); layout.js hands in its geometry helpers so the Stage 1-5
// outputs stay byte-identical.
export function stage6RingSpecs(stage) {
  if (stage !== 6) return null;
  return [
    ['ring-db', 'RING 1 · DATABASE'],
    ['ring-workers', 'RING 2 · WORKERS'],
    ['ring-cache', 'RING 3 · CACHE'],
    ['ring-compute', 'RING 4 · WEBSERVERS'],
    ['ring-lb', 'RING 5 · LOADBALANCER'],
    ['ring-network', 'RING 6 · NETWORK'],
    ['ring-dns', 'RING 7 · DNS'],
    ['ring-clients', 'RING 8 · BROWSERS'],
  ];
}

export function addStage6Nodes({ rings, nodes, wires, pos, makeWire }) {
  const dnsRing = rings.find((ring) => ring.id === 'ring-dns');
  const networkRing = rings.find((ring) => ring.id === 'ring-network');
  nodes['node-dns'] = pos('node-dns', 'ring-dns', dnsRing.radius, 180);
  // The Router renders as a side-card on the Network ring, off the 10.x
  // hub's 180° seat, with its own chord wire.
  nodes['node-router'] = pos('node-router', 'ring-network', networkRing.radius, 160);
  wires.push(
    makeWire(
      'wire-browser-dns',
      'node-browser',
      'node-dns',
      nodes['node-browser'],
      nodes['node-dns'],
    ),
    makeWire(
      'wire-network-router',
      'node-network',
      'node-router',
      nodes['node-network'],
      nodes['node-router'],
    ),
  );
}

// DOCUMENTS: wire-lane anchoring config, split from viewport.js by
// responsibility (guard-file-size: viewport.js sits at its 300-line cap and
// Stage 6 adds the DNS and Router lanes). Each stage maps a lane element id
// to the wire it sits on (optionally at a fraction t down that wire —
// Stage 5 anchors the cache→db lane at t = 0.3 so it clears the queue→worker
// crossing); LANES_BETWEEN anchors a lane between two parallel wires, with
// an optional cap toward a card the lane would otherwise clip.
export const LANE_WIRES = {
  1: { 'wire-col-left': 'wire-browser-network', 'wire-col-right': 'wire-network-webserver' },
  2: { 'wire-col-left': 'wire-browser-network', 'wire-col-right': 'wire-network-lb' },
  3: { 'wire-col-left': 'wire-browser-network', 'wire-col-right': 'wire-network-lb' },
  4: {
    'wire-col-left': 'wire-browser-network',
    'wire-col-right': 'wire-network-lb',
    'wire-cache-db': 'wire-cache-db',
  },
  5: {
    'wire-col-left': 'wire-browser-network',
    'wire-col-right': 'wire-network-lb',
    'wire-cache-db': ['wire-cache-db', 0.3],
    'wire-cache-queue': 'wire-cache-queue',
    'wire-queue-worker': 'wire-queue-worker',
  },
  6: {
    'wire-col-left': 'wire-browser-network',
    'wire-col-right': 'wire-network-lb',
    'wire-col-dns': 'wire-browser-dns',
    'wire-col-router': 'wire-network-router',
    'wire-cache-db': ['wire-cache-db', 0.3],
    'wire-cache-queue': 'wire-cache-queue',
    'wire-queue-worker': 'wire-queue-worker',
  },
};

export const LANES_BETWEEN = [
  {
    laneId: 'wire-lb-backends',
    stages: [2, 3, 4, 5, 6],
    wireIds: ['wire-lb-webserver', 'wire-lb-webserver-2'],
  },
  {
    laneId: 'wire-servers-cache',
    stages: [3, 4, 5, 6],
    wireIds: ['wire-webserver-cache', 'wire-webserver-2-cache'],
    capTo: 'node-cache',
    capDx: -175, // 15.5rem card half + chip half + margin, in world px
  },
];

