// Which card executes the hop, and which wire lane carries it:
// Stage 1 is emit / route / serve / render; Stage 2 inserts the LB's
// round-robin pick; Stage 3 splits the backend serve into the cache
// lookup (Cache 10.20 answers) and the response emission; Stage 4 adds
// the database hop; Stage 5 adds async worker queue processing.
// CHECKS: the Stage 6 mapping branches on the trace shape — host-less
// traces reuse the Stage 5 owners/lanes per hop, hosted traces shift the
// Stage 5 chain two hops out behind the DNS ask/answer pair, and an NX
// trace lights the browser and DNS cards with no server card at all.
function stage5HopTarget(snapshot) {
  const hop = snapshot.trace?.hop ?? 0;
  const backendCard =
    snapshot.trace?.targetServer === '10.12' ? 'node-webserver-2' : 'node-webserver';
  const dbLane = snapshot.trace?.dbOp === 'WRITE' ? 'packet-req-db' : 'packet-res-db';
  if (snapshot.trace?.asyncJob) {
    const owners = {
      1: 'node-browser',
      2: 'node-network',
      3: 'node-lb',
      4: 'node-queue',
      5: 'node-webserver',
      6: 'node-network',
      7: 'node-browser',
      8: 'node-worker',
    };
    const lanes = {
      1: 'packet-req-left',
      2: 'packet-req-right',
      3: 'packet-req-lb',
      4: 'packet-req-queue',
      5: 'packet-res-cache',
      6: 'packet-res-right',
      7: 'packet-res-left',
      8: 'packet-res-db',
    };
    return { cardId: owners[hop] ?? 'node-browser', laneId: lanes[hop] ?? 'packet-req-left' };
  }
  const owners = {
    1: 'node-browser',
    2: 'node-network',
    3: 'node-lb',
    4: 'node-db',
    5: backendCard,
    6: 'node-network',
    7: 'node-browser',
    8: 'node-worker',
  };
  const lanes = {
    1: 'packet-req-left',
    2: 'packet-req-right',
    3: 'packet-req-lb',
    4: dbLane,
    5: 'packet-res-cache',
    6: 'packet-res-right',
    7: 'packet-res-left',
    8: 'packet-res-worker',
  };
  return { cardId: owners[hop] ?? 'node-browser', laneId: lanes[hop] ?? 'packet-req-left' };
}

function activeHopTarget(snapshot) {
  const hop = snapshot.trace?.hop ?? 0;
  if (snapshot.stage === 6) {
    const t = snapshot.trace ?? {};
    if (t.nx) {
      const owners = { 1: 'node-browser', 2: 'node-dns', 3: 'node-browser' };
      const lanes = {
        1: 'packet-req-dns',
        2: 'packet-res-dns',
        3: 'packet-res-left',
      };
      return { cardId: owners[hop] ?? 'node-browser', laneId: lanes[hop] ?? 'packet-req-dns' };
    }
    if (t.hosted) {
      const stage5 = stage5HopTarget({ ...snapshot, trace: { ...t, hop: hop - 2 } });
      const dnsOwners = { 1: 'node-browser', 2: 'node-dns' };
      const dnsLanes = { 1: 'packet-req-dns', 2: 'packet-res-dns' };
      if (hop <= 2) {
        return { cardId: dnsOwners[hop] ?? 'node-browser', laneId: dnsLanes[hop] ?? 'packet-req-dns' };
      }
      return stage5;
    }
    return stage5HopTarget(snapshot);
  }
  if (snapshot.stage === 5) {
    return stage5HopTarget(snapshot);
  }

