import { describe, it, expect } from 'vitest';
import { createDns } from '../../js/sim/dns.js';

describe('createDns', () => {
  it('resolves example.com authoritatively on miss and records the ledger entry', () => {
    const dns = createDns({ address: '10.60', ttlTicks: 300 });
    const miss = dns.lookup('example.com', 0);
    expect(miss).toEqual({ status: 'MISS', target: '10.1' });
    expect(dns.snapshot(0)).toMatchObject({
      address: '10.60',
      ttlTicks: 300,
      lookups: 1,
      cachedHits: 0,
      authoritative: 1,
    });
    expect(dns.snapshot(0).cache).toEqual([
      { name: 'example.com', target: '10.1', expiresAtTick: 300, ttlRemaining: 300 },
    ]);
    expect(dns.snapshot(5).lastLookup).toEqual({
      name: 'example.com',
      status: 'MISS',
      target: '10.1',
      atTick: 0,
    });
  });

  // PINS: negative-case contract — a hit inside ttlTicks increments
  // cachedHits with NO authoritative consult (the authoritative counter
  // stays at 1 after two lookups).
  it('a DNS cache hit inside ttlTicks increments cachedHits with no authoritative consult', () => {
    const dns = createDns({ ttlTicks: 300 });
    dns.lookup('example.com', 0);
    const hit = dns.lookup('example.com', 299);
    expect(hit).toEqual({ status: 'HIT', target: '10.1' });
    const snap = dns.snapshot(299);
    expect(snap).toMatchObject({ lookups: 2, cachedHits: 1, authoritative: 1 });
    expect(snap.lastLookup).toEqual({
      name: 'example.com',
      status: 'HIT',
      target: '10.1',
      atTick: 299,
    });
  });

  // PINS: negative-case contract — an expired entry is dropped before it
  // can answer, so the next lookup is an authoritative MISS, not a stale
  // ledger hit; cachedHits stays put and the TTL restarts on the refill.
  it('an expired entry never answers from the ledger', () => {
    const dns = createDns({ ttlTicks: 10 });
    dns.lookup('example.com', 0);
    // Tick 10 is the first tick the entry is gone (expiresAtTick = 10).
    expect(dns.lookup('example.com', 10)).toEqual({ status: 'MISS', target: '10.1' });
    const snap = dns.snapshot(10);
    expect(snap).toMatchObject({ lookups: 2, cachedHits: 1, authoritative: 2, evictions: 1 });
    expect(snap.cache).toEqual([
      { name: 'example.com', target: '10.1', expiresAtTick: 20, ttlRemaining: 10 },
    ]);
    // A lookup past expiry inside the same call cannot double-evict.
    dns.lookup('example.com', 25);
    expect(dns.snapshot(25).evictions).toBe(2);
  });

  // PINS: negative-case contract — an unknown name answers { status: 'NX' }
  // at the DNS layer (the browser renders the NX card); the DNS component
  // itself does not throw, and the NX answer writes no ledger entry.
  it('unknown names answer NX instead of throwing at the DNS layer', () => {
    const dns = createDns();
    expect(() => dns.lookup('nope.example', 0)).not.toThrow();
    expect(dns.lookup('nope.example', 0)).toEqual({ status: 'NX' });
    expect(dns.lookup('nope.example', 1)).toEqual({ status: 'NX' });
    const snap = dns.snapshot(1);
    expect(snap).toMatchObject({ lookups: 3, cachedHits: 0, authoritative: 3 });
    expect(snap.cache).toEqual([]);
    expect(snap.lastLookup).toEqual({ name: 'nope.example', status: 'NX', atTick: 1 });
  });

  // CHECKS: the constructor rejects a non-mini-IP address and a
  // non-positive or non-integer ttlTicks (fail-loud over silent misconfig).
  it('rejects a non mini-IP address and a non-positive or non-integer ttlTicks', () => {
    expect(() => createDns({ address: '1060' })).toThrow(/invalid mini-IP/);
    expect(() => createDns({ ttlTicks: 0 })).toThrow(/ttlTicks/);
    expect(() => createDns({ ttlTicks: 2.5 })).toThrow(/ttlTicks/);
  });
});

import { describe, it, expect } from 'vitest';
import { createNetwork } from '../../js/sim/network.js';
import { createRouter } from '../../js/sim/router.js';
import { createWebServer } from '../../js/sim/webserver.js';

describe('createRouter', () => {
  // PINS: the same-subnet contract is untouched by the router's presence —
  // send/deliverToQueue resolve locally, `routed` stays 0, and isYou marks
  // the queue row exactly as before.
  it('same-subnet sends keep the send and deliverToQueue contract unchanged', () => {
    const left = createNetwork();
    const server = createWebServer({ address: '10.1' });
    left.registerServer('10.1', server);
    const router = createRouter();
    router.join(left, createNetwork({ subnet: '20' }));

    expect(left.send({ from: '10.2', to: '10.1', request: 'GET /about' })).toEqual({
      from: '10.2',
      to: '10.1',
      request: 'GET /about',
      response: '200 This is the about page',
    });
    left.deliverToQueue({
      id: 'q:1',
      from: '10.2',
      to: '10.1',
      request: 'GET /about',
      atTick: 1,
      isYou: true,
    });
    expect(server.queueSnapshot()).toEqual([
      { id: 'q:1', atTick: 1, from: '10.2', to: '10.1', request: 'GET /about', isYou: true },
    ]);
    expect(router.snapshot()).toMatchObject({ routed: 0, lastRoute: null });
  });

  // PINS: a cross-subnet frame crosses exactly one router hop — `routed`
  // counts 1 — and the router's own 20-side interface is the reachable
  // target in subnet 20 (Stage 6a's only tenant there).
  it('cross-subnet frames take exactly one router hop through 10.65 ⇄ 20.1', () => {
    const left = createNetwork();
    const right = createNetwork({ subnet: '20' });
    const router = createRouter();
    router.join(left, right);

    const reply = left.send({ from: '10.2', to: '20.1', request: 'GET /' });
    expect(reply).toEqual({
      from: '10.2',
      to: '20.1',
      request: 'GET /',
      response: '200 router 20.1',
    });
    const snap = router.snapshot();
    expect(snap.routed).toBe(1);
    expect(snap.lastRoute).toBe('10.2 -> 20.1 via 10.65 ⇄ 20.1');

    // The router's left interface answers same-subnet sends locally, with
    // no routed hop.
    expect(left.send({ from: '10.2', to: '10.65', request: 'GET /' })).toMatchObject({
      to: '10.65',
      response: '200 router 20.1',
    });
    expect(router.snapshot().routed).toBe(1);
  });

  // PINS: negative-case contract — a send into subnet 20 to an unregistered
  // host throws (fail-loud, mirroring network.js's resolve); the error
  // surfaces from the far network, and the frame still counted its single
  // router hop on the way in.
  it('a send into subnet 20 to an unregistered host 20.9 throws', () => {
    const left = createNetwork();
    const router = createRouter();
    router.join(left, createNetwork({ subnet: '20' }));
    expect(() => left.send({ from: '10.2', to: '20.9', request: 'GET /' })).toThrow(
      /no server at 20\.9/,
    );
    expect(() =>
      left.deliverToQueue({ id: 'q:1', from: '10.2', to: '20.9', request: 'GET /', atTick: 1 }),
    ).toThrow(/no server at 20\.9/);
    expect(router.snapshot().routed).toBe(2);
  });

  // PINS: `isYou` rides through the router untouched on cross-subnet queue
  // delivery — the far network's enqueue receives the same record shape.
  it('isYou rides through the router on cross-subnet queue delivery', () => {
    const left = createNetwork();
    const right = createNetwork({ subnet: '20' });
    const router = createRouter();
    router.join(left, right);
    let received = null;
    right.registerServer('20.5', {
      handleRequest: () => '200 edge',
      enqueue: (record) => {
        received = record;
      },
    });
    left.deliverToQueue({
      id: 'you:1',
      from: '10.2',
      to: '20.5',
      request: 'GET /edge',
      atTick: 1,
      isYou: true,
    });
    expect(received).toEqual({
      id: 'you:1',
      atTick: 1,
      from: '10.2',
      to: '20.5',
      request: 'GET /edge',
      isYou: true,
    });
    expect(router.snapshot().routed).toBe(1);
  });

  // CHECKS: the constructor rejects a non two-number mini-IP interface and
  // two interfaces on the same subnet (fail-loud over silent misconfig).
  it('rejects invalid mini-IP interfaces and a same-subnet pair', () => {
    expect(() => createRouter({ leftAddress: '1065' })).toThrow(/mini-IP/);
    expect(() => createRouter({ leftAddress: '10.65', rightAddress: '10.66' })).toThrow(
      /same subnet/,
    );
  });
});

import { describe, it, expect } from 'vitest';
import { createEngine } from '../../js/sim/engine.js';

describe('stage 6 engine — DNS ledger + hosted traces', () => {
  // CHECKS: stage 6 instantiates DNS 10.60 and the Router (10.65 ⇄ 20.1)
  // and exposes both on the snapshot; the stage range now validates 1-6
  // with the same error shape.
  it('stage 6 engine exposes DNS 10.60 and Router 10.65 ⇄ 20.1 in the snapshot', () => {
    const snap = createEngine({ stage: 6 }).snapshot();
    expect(snap.dns).toMatchObject({ address: '10.60', ttlTicks: 300, lookups: 0 });
    expect(snap.router).toMatchObject({
      leftAddress: '10.65',
      rightAddress: '20.1',
      routed: 0,
    });
    expect(createEngine({ stage: 5 }).snapshot().dns).toBe(null);
    expect(createEngine({ stage: 5 }).snapshot().router).toBe(null);
    expect(() => createEngine({ stage: 7 })).toThrow(
      /stage must be 1, 2, 3, 4, 5, or 6, got 7/,
    );
  });

  // PINS: the hosted grammar — the browser URL splits host/path on the
  // first "/", the ask rides Browser -> DNS, the answer rides DNS ->
  // Browser, and only then does the browser emit the GET with the resolved
  // target; the trace totals 10 hops (Stage 5's 8 + 2) and the ledger
  // counts the authoritative consult.
  it('hosted example.com/about adds exactly 2 DNS hops to the stage-5 story', () => {
    const engine = createEngine({ stage: 6 });
    engine.traceHop({ method: 'GET', path: 'example.com/about' });
    let snap = engine.snapshot();
    expect(snap.trace.hop).toBe(1);
    expect(snap.trace.hosted).toBe(true);
    expect(snap.lastFrame).toBe('10.2 -> 10.60 | resolve example.com');

    engine.traceHop();
    snap = engine.snapshot();
    expect(snap.trace.hop).toBe(2);
    expect(snap.lastFrame).toBe('10.60 -> 10.2 | example.com is 10.1 (authoritative)');

    engine.traceHop();
    snap = engine.snapshot();
    expect(snap.trace.hop).toBe(3);
    expect(snap.lastFrame).toBe('10.2 -> 10.1 | GET /about');

    for (let i = 0; i < 7; i++) engine.traceHop();
    snap = engine.snapshot();
    expect(snap.trace.hop).toBe(10);
    expect(snap.browserDisplay.body).toBe('This is the about page');
    expect(snap.dns).toMatchObject({ lookups: 1, cachedHits: 0, authoritative: 1 });
    expect(snap.dns.cache[0]).toMatchObject({ name: 'example.com', target: '10.1' });

    // The second hosted trace's answer rides the ledger: cachedHits +1, no
    // new authoritative consult.
    engine.traceHop({ method: 'GET', path: 'example.com/about' });
    engine.traceHop();
    snap = engine.snapshot();
    expect(snap.lastFrame).toBe('10.60 -> 10.2 | example.com is 10.1 (cache HIT)');
    expect(snap.dns).toMatchObject({ lookups: 2, cachedHits: 1, authoritative: 1 });
  });

  // PINS: negative-case contract — an unknown name never emits a GET: the
  // trace is the DNS ask plus the "NX no record" answer, the browser
  // renders the NX card, no server queue row exists, and the NX answer
  // writes no ledger entry.
  it('nope.example/about never emits a GET — DNS ask plus NX answer only', () => {
    const engine = createEngine({ stage: 6 });
    engine.traceHop({ method: 'GET', path: 'nope.example/about' });
    expect(engine.snapshot().lastFrame).toBe('10.2 -> 10.60 | resolve nope.example');
    engine.traceHop();
    expect(engine.snapshot().lastFrame).toBe('10.60 -> 10.2 | NX no record');
    engine.traceHop();
    const snap = engine.snapshot();
    expect(snap.lastFrame).toBe('Browser 10.2 renders NX — no record for nope.example');
    expect(snap.trace).toMatchObject({ hop: 3, hosted: true, nx: true, status: 'NX' });
    expect(snap.browserDisplay).toMatchObject({ status: 'NX', body: 'no record' });
    expect(snap.servers.every((s) => s.queueDepth === 0)).toBe(true);
    expect(snap.served).toBe(0);
    expect(snap.dns.cache).toEqual([]);
  });

  // PINS: negative-case contract — a host-less path on Stage 6 keeps the
  // Stage 5 hop story byte-identical, frame for frame, and the DNS ledger
  // is left untouched (no ask, no consult).
  it('GET /about on stage 6 keeps the stage-5 hop story byte-identical — no DNS hop', () => {
    const frames = (stage) => {
      const engine = createEngine({ stage });
      const out = [];
      for (let i = 0; i < 8; i++) {
        engine.traceHop({ method: 'GET', path: '/about' });
        out.push(engine.snapshot().lastFrame);
      }
      return out;
    };
    const stage5 = frames(5);
    const stage6 = frames(6);
    expect(stage6).toEqual(stage5);
    expect(stage6[0]).toBe('10.2 -> 10.1 | GET /about');
    const snap = createEngine({ stage: 6 }).snapshot();
    expect(snap.trace).toMatchObject({ hosted: false, hop: 0 });
    expect(snap.dns.lookups).toBe(0);
  });

  // Stage 6 keeps the whole Stage 5 async story for a hosted POST too: the
  // 2 DNS hops ride ahead, the 202 path and the worker commit stay intact.
  it('hosted POST /jobs keeps the async story behind the 2 DNS hops', () => {
    const engine = createEngine({ stage: 6 });
    engine.traceHop({ method: 'POST', path: 'example.com/jobs' });
    engine.traceHop();
    for (let i = 0; i < 8; i++) engine.traceHop();
    const snap = engine.snapshot();
    expect(snap.trace.hop).toBe(10);
    expect(snap.trace.asyncJob).toBe(true);
    expect(snap.browserDisplay.body).toBe('{"jobId": 1, "status": "queued"}');
    expect(snap.workerQueue.enqueued).toBe(1);
  });
});

import { describe, it, expect } from 'vitest';
import { describeSnapshot, totalHopsFor } from '../../js/panel/model.js';
import { formatComponentState, componentTitle } from '../../js/panel/inspector-state.js';
import { computeStageLayout } from '../../js/panel/layout.js';

// Stage-boundary extraction (guard-file-size): the Stage 6 DNS/Router
// narrative-branch pins live here so model.test.js keeps its Stage 1/2
// scope. All three brief contracts are pinned with their named
// counter-examples.
const baseTrace = {
  method: 'GET',
  path: '/about',
  request: 'GET /about',
  from: '10.2',
  targetServer: '10.11',
  cacheStatus: 'HIT',
  dbOp: null,
  dbStale: false,
  asyncJob: false,
  response: '200 This is the about page',
  status: 200,
  body: 'This is the about page',
  routeId: 'about',
};

const stage5Snapshot = (trace) => ({
  stage: 5,
  tick: 1,
  users: 5,
  serverAddress: '10.1',
  queueDepth: 0,
  served: 1,
  avgLatencyTicks: 1,
  workerQueue: {
    address: '10.40',
    workerAddress: '10.41',
    jobDurationTicks: 2,
    enqueued: 0,
    completed: 0,
    activeJob: null,
    pendingJobs: [],
    lastJobResult: null,
  },
  trace,
});

const stage6Snapshot = (trace) => ({
  ...stage5Snapshot(trace),
  stage: 6,
  dns: {
    address: '10.60',
    ttlTicks: 300,
    lookups: 1,
    cachedHits: 0,
    authoritative: 1,
    evictions: 0,
    lastLookup: { name: 'example.com', status: 'MISS', target: '10.1', atTick: 0 },
    cache: [{ name: 'example.com', target: '10.1', expiresAtTick: 300, ttlRemaining: 300 }],
  },
  router: { leftAddress: '10.65', rightAddress: '20.1', routed: 0, lastRoute: null },
});

const hopAt = (snapshot, hop) =>
  describeSnapshot({ ...snapshot, trace: { ...snapshot.trace, hop } }).hopStatus;

describe('stage 6 narrative branches', () => {
  // PINS: negative-case contract — GET /about on Stage 6 keeps the Stage 5
  // hop story byte-identical, sentence for sentence, and totals 8 hops.
  it('GET /about on stage 6 keeps the stage-5 hop story byte-identical — no DNS hop', () => {
    const trace = { ...baseTrace, hosted: false, nx: false };
    const stage5 = describeSnapshot(stage5Snapshot(trace));
    const stage6 = describeSnapshot(stage6Snapshot(trace));
    expect(stage6.totalHops).toBe(8);
    for (let hop = 1; hop <= 8; hop++) {
      expect(hopAt(stage6Snapshot(trace), hop)).toBe(hopAt(stage5Snapshot(trace), hop));
    }
    expect(hopAt(stage6Snapshot(trace), 1)).toBe('Hop 1/8: Browser (10.2) emits "GET /about"');
    expect(hopAt(stage6Snapshot(trace), 8)).toBe(
      'Hop 8/8: Worker (10.41) idle — no async jobs in this trace',
    );
    expect(totalHopsFor(6, { hosted: false })).toBe(8);
  });

  // PINS: the hosted grammar — hop 1 is the DNS ask, hop 2 the answer, and
  // the Stage 5 sentences repeat renumbered onto 10 hops; the total is
  // Stage 5's 8 + exactly 2 DNS hops.
  it('hosted example.com/about adds exactly 2 DNS hops to the stage-5 story', () => {
    const trace = {
      ...baseTrace,
      path: 'example.com/about',
      hosted: true,
      nx: false,
      dnsName: 'example.com',
      dnsAddress: '10.60',
      dnsAnswer: 'example.com is 10.1 (authoritative)',
    };
    const snap = stage6Snapshot(trace);
    expect(describeSnapshot(snap).totalHops).toBe(10);
    expect(hopAt(snap, 1)).toBe('Hop 1/10: Browser (10.2) asks DNS (10.60) for example.com');
    expect(hopAt(snap, 2)).toBe(
      'Hop 2/10: DNS (10.60) -> 10.2 | example.com is 10.1 (authoritative)',
    );
    expect(hopAt(snap, 3)).toBe('Hop 3/10: Browser (10.2) emits "GET /about"');
    expect(hopAt(snap, 10)).toBe('Hop 10/10: Worker (10.41) idle — no async jobs in this trace');
    expect(totalHopsFor(6, { hosted: true })).toBe(10);
  });

  // PINS: negative-case contract — the NX path never emits a GET: the
  // narrative is ask, "NX no record" answer, and the browser rendering the
  // NX card; the total is 3.
  it('nope.example/about renders NX without emitting a GET', () => {
    const trace = {
      ...baseTrace,
      path: 'nope.example/about',
      request: 'GET nope.example/about',
      response: 'NX no record',
      status: 'NX',
      body: 'no record',
      hosted: true,
      nx: true,
      dnsName: 'nope.example',
      dnsAddress: '10.60',
      dnsAnswer: 'NX no record',
      targetServer: null,
    };
    const snap = stage6Snapshot(trace);
    expect(describeSnapshot(snap).totalHops).toBe(3);
    expect(hopAt(snap, 1)).toBe('Hop 1/3: Browser (10.2) asks DNS (10.60) for nope.example');
    expect(hopAt(snap, 2)).toBe('Hop 2/3: DNS (10.60) -> 10.2 | NX no record');
    expect(hopAt(snap, 3)).toBe('Hop 3/3: Browser (10.2) renders NX — no record for nope.example');
    expect(totalHopsFor(6, { hosted: true, nx: true })).toBe(3);
    // Stage 5 has no NX branch: its total stays 8 whatever the trace says.
    expect(totalHopsFor(5, { hosted: true, nx: true })).toBe(8);
  });

  it('exposes the DNS ledger and Router counters as labels and inspector state', () => {
    const snap = stage6Snapshot({ ...baseTrace, hosted: false });
    const labels = describeSnapshot(snap);
    expect(labels.dnsStatsLabel).toBe('Lookups: 1 · Cached hits: 0 · TTL: 300t');
    expect(labels.dnsEntries).toEqual(snap.dns.cache);
    expect(labels.routerLabel).toBe('Routed: 0 · 10.65 ⇄ 20.1');

    const dnsState = JSON.parse(formatComponentState(snap, 'dns'));
    expect(dnsState).toEqual(snap.dns);
    expect(componentTitle(snap, 'dns')).toBe('DNS — mini-IP 10.60');
    const routerState = JSON.parse(formatComponentState(snap, 'router'));
    expect(routerState).toEqual(snap.router);
    expect(componentTitle(snap, 'router')).toBe('Router — 10.65 ⇄ 20.1');
    const networkState = JSON.parse(formatComponentState(snap, 'network'));
    expect(networkState.interfaces['10.60']).toBe('DNS');
    expect(networkState.interfaces['10.65']).toBe('Router (left)');
    expect(networkState.interfaces['20.1']).toBe('Router (right)');
  });

  it('lays out the eight-ring Stage 6 orrery with DNS on Ring 7 and the Router on Ring 6', () => {
    const stage6 = computeStageLayout(6, 5);
    expect(stage6.rings.map((r) => r.id)).toEqual([
      'ring-db',
      'ring-workers',
      'ring-cache',
      'ring-compute',
      'ring-lb',
      'ring-network',
      'ring-dns',
      'ring-clients',
    ]);
    expect(stage6.rings.map((r) => r.radius)).toEqual([
      400, 800, 1200, 1600, 2000, 2400, 2800, 3200,
    ]);
    expect(stage6.nodes['node-dns']).toMatchObject({ x: -2800, y: 0, ring: 'ring-dns' });
    expect(stage6.nodes['node-router']).toMatchObject({ ring: 'ring-network' });
    expect(stage6.nodes['node-browser']).toMatchObject({ x: -3200, y: 0, ring: 'ring-clients' });
    expect(stage6.wires.map((w) => w.id)).toEqual([
      'wire-browser-network',
      'wire-network-lb',
      'wire-lb-webserver',
      'wire-lb-webserver-2',
      'wire-webserver-cache',
      'wire-webserver-2-cache',
      'wire-cache-db',
      'wire-cache-queue',
      'wire-queue-worker',
      'wire-worker-db',
      'wire-browser-dns',
      'wire-network-router',
    ]);
    expect(stage6.bounds).toEqual({ minX: -3380, maxX: 120, minY: -540, maxY: 540 });
  });
});

