// Stage 5's trace story, parameterized by the denominator and the first hop
// number so Stage 6's hosted tail renumbers the same sentences onto hops
// 3-10 of 10. Stage 5 passes denom 8 / start 1 — byte-identical to the
// pre-Stage-6 strings.
function stage5Sentences(t, snapshot, from, serverAddress, denom, start = 1) {
  const target = t.targetServer ?? '10.11';
  const worker = snapshot.workerQueue?.workerAddress ?? '10.41';
  const at = (k) => `Hop ${start + k - 1}/${denom}`;
  if (t.asyncJob) {
    return [
      `${at(1)}: Browser (${from}) emits "${t.request}"`,
      `${at(2)}: Network (10.x) routes to LoadBalancer (${serverAddress})`,
      `${at(3)}: LoadBalancer (${serverAddress}) -> ${target} queue`,
      `${at(4)}: WebServer (${target}) enqueues job to WorkerQueue (10.40)`,
      `${at(5)}: WebServer (${target}) -> "202 Accepted"`,
      `${at(6)}: Network delivers 202 response to ${from}`,
      `${at(7)}: Browser (${from}) received and displayed 202 Accepted`,
      `${at(8)}: Worker (${worker}) processed job and committed to Database (10.30)`,
    ];
  }
  // Requests served synchronously keep the Stage 4 cache/database story;
  // the worker does not see them, so the tail hop reads idle.
  const db = snapshot.database ?? {};
  const primary = db.primaryAddress ?? '10.30';
  const replica = db.replicaAddress ?? '10.31';
  const lag = db.replicationLagTicks ?? 3;
  const dbOp =
    t.dbOp === 'WRITE'
      ? `Database WRITE @ Primary (${primary}) — replica lags ${lag}t`
      : t.dbOp === 'SELECT' && t.dbStale
        ? `Database SELECT @ Replica (${replica}) — STALE (lag ${lag}t)`
        : t.dbOp === 'SELECT'
          ? `Database SELECT @ Replica (${replica}) — fresh`
          : `Database SKIP — warm cache HIT (${snapshot.cache?.address ?? '10.20'})`;
  return [
    `${at(1)}: Browser (${from}) emits "${t.request}"`,
    `${at(2)}: Network (10.x) routes to LoadBalancer (${serverAddress})`,
    `${at(3)}: LoadBalancer (${serverAddress}) -> ${target} queue`,
    `${at(4)}: ${dbOp}`,
    `${at(5)}: WebServer (${target}) -> "${t.response}" (cache ${t.cacheStatus})`,
    `${at(6)}: Network delivers ${t.status} response to ${from}`,
    `${at(7)}: Browser (${from}) received and displayed ${t.status}`,
    `${at(8)}: Worker (${worker}) idle — no async jobs in this trace`,
  ];
}

